class FontSizeManager{constructor(){this.sizes=["small","medium","large"],this.currentSize=this.loadSize(),this.init()}init(){this.applySize(this.currentSize)}loadSize(){return localStorage.getItem("reader_fontSize")||"small"}saveSize(e){localStorage.setItem("reader_fontSize",e)}changeSize(e){this.sizes.includes(e)?(this.currentSize=e,this.saveSize(e),this.applySize(e)):console.error(`Invalid font size: ${e}`)}applySize(e){const t=document.body;this.sizes.forEach(e=>{t.classList.remove(`font-${e}`)}),t.classList.add(`font-${e}`)}increaseFontSize(){const e=this.sizes.indexOf(this.currentSize);if(e<this.sizes.length-1){const t=this.sizes[e+1];return this.changeSize(t),t}return this.currentSize}decreaseFontSize(){const e=this.sizes.indexOf(this.currentSize);if(e>0){const t=this.sizes[e-1];return this.changeSize(t),t}return this.currentSize}getSize(){return this.currentSize}isSmall(){return"small"===this.currentSize}isMedium(){return"medium"===this.currentSize}isLarge(){return"large"===this.currentSize}}const fontSizeManager=new FontSizeManager;document.addEventListener("keydown",e=>{!e.ctrlKey&&!e.metaKey||e.shiftKey||("="===e.key||"+"===e.key?(e.preventDefault(),fontSizeManager.increaseFontSize()):"-"===e.key?(e.preventDefault(),fontSizeManager.decreaseFontSize()):"0"===e.key&&(e.preventDefault(),fontSizeManager.changeSize("small")))});export{fontSizeManager};